/// <summary>
///     AVA <c>Image1Name_OnLookup</c> method.
///     AVA - Schneider 06.08.2024
/// </summary>
/// <param name="sender">
///     <c>FormControl</c> as type
/// </param>
/// <param name="e">
///     <c>FormControlEventArgs</c> as type
/// </param>
[FormControlEventHandler(formControlStr(SysDocuBrandDetails, AVAAxpDocuBrandDocumentTable_Image1NameInternational), FormControlEventType::Lookup)]
public static void Image1Name_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;

    AVASysDocuBrandDetailsfrm_ImageNameLookup_EventHandler::avaLookupImageName(sender);

    ce.CancelSuperCall();
}

