/// <summary>
///     AVA <c>avaLookupImageName</c> method.
///     AVA - Schneider 06.08.2024
/// </summary>
/// <param name="_formStringControl">
///     <c>FormStringControl</c> as type
/// </param>
public static void avaLookupImageName(FormStringControl _formStringControl)
{
    SysTableLookup          locSysTableLookup;
    Query                   locQuery;
    QueryBuildDataSource    locQBDS;

    locQuery            = new Query();

    locQBDS             = locQuery.addDataSource(tableNum(SysDocuBrandImages));

    locSysTableLookup   = SysTableLookup::newParameters(tableNum(SysDocuBrandImages), _formStringControl);
    locSysTableLookup.addLookupfield(fieldNum(SysDocuBrandImages, Name));
    locSysTableLookup.addLookupfield(fieldNum(SysDocuBrandImages, Description));
    locSysTableLookup.parmQuery(locQuery);
    locSysTableLookup.performFormLookup();
}
